    String extensions = script.isEmpty() ? suffix : suffix.length() == 4 ? "" : suffix.substring(5);
    Locale tags = Locale.forLanguageTag("und" + (script.isEmpty() ? "" : "-" + script)
        + (extensions.isEmpty() ? "" : "-" + extensions));
