    if (script.isEmpty() && tags.getExtensionKeys().equals(locale.getExtensionKeys())
        && tags.getExtensionKeys().stream().allMatch(key -> tags.getExtension(key).equals(locale.getExtension(key)))) {
      return locale;
    }
